func isGraphQLNameStart(b byte) bool {
	return b == '_' || (b >= 'A' && b <= 'Z') || (b >= 'a' && b <= 'z')
}

func isGraphQLNameContinue(b byte) bool {
	return isGraphQLNameStart(b) || (b >= '0' && b <= '9')
}
